  at(24,()=>{grey.animate([{opacity:1},{opacity:0}],{duration:220,fill:'forwards'});pa=pill.animate([{opacity:0},{opacity:1}],{duration:200,fill:'forwards'})});
  at(120,()=>{pill.style.background='#f0243a';$('i',pill).style.opacity=1;ember.style.background='#5a2b33'});
  at(273,()=>{if(pa)pa.cancel();pill.style.opacity=0;lit.style.opacity=1});
  at(40,()=>rv(odo,'a-fade'));
  E(0,()=>playClip(0));E(80,null,'tick');
  /* leap + orange ribbons */
  E(300,sfx.fire,'medium',()=>{
    burst(180,356,10,{colors:['#ff9a3a'],round:true,size:[2,4],speed:90,fall:40,life:900});
    $$('.cr').forEach((c,k)=>{const a=[-20,140,250][k];c.animate([{transform:`rotate(${a}deg) scale(.3)`,opacity:0},{transform:`rotate(${a+70}deg) scale(.62)`,opacity:1,offset:.25},{transform:`rotate(${a+240}deg) scale(.8)`,opacity:0}],{duration:680,delay:k*110,easing:'ease-out',fill:'both'})});
    at(170,()=>burst(180,123,14,{colors:['#ff9a3a','#ffb347'],size:[5,10],speed:150,fall:30,life:750}));
  });
  at(370,()=>{rv(dl,'a-fade');dl.style.opacity='.55'});
  /* number swap 6 -> 7 */
  E(488,()=>sfx.tick(3),'light',()=>{
    o1.animate([{transform:'translate(0,0) rotate(0)',opacity:1},{transform:'translate(-16px,70px) rotate(-14deg)',opacity:0}],{duration:240,easing:'ease-in',fill:'forwards'});
    o2.animate([{transform:'translate(40px,-70px) rotate(14deg)',opacity:0},{transform:'translate(0,0) rotate(0)',opacity:1}],{duration:300,delay:90,easing:'cubic-bezier(.2,1.2,.4,1)',fill:'forwards'});
    dl.style.color='#b0222f'});
  E(658,sfx.big,'medium',()=>{o2.style.color='#ff9a3a';o2.style.webkitTextStroke='3px #ffd9ae';o2.animate([{transform:'translate(0,-8px) scale(1.07)'},{transform:'translate(0,0) scale(1)'}],{duration:350,fill:'forwards'});dl.style.color='#f0432e'});
  at(735,()=>{const l=$('.lick');l.animate([{opacity:0,transform:'scale(.3)'},{opacity:1,transform:'scale(1.1)'},{opacity:1,transform:'scale(.9)'}],{duration:280,fill:'forwards'})});
