const INTRO_B64='';
const MASC=["data:image/png;base64,"];
let IB=null,IS=null,IGN=null,IBP=null;
function introLoad(){const c=ctx(true);if(!c)return Promise.resolve();return IBP||(IBP=(async()=>{try{const s=atob(INTRO_B64),u=new Uint8Array(s.length);for(let i=0;i<s.length;i++)u[i]=s.charCodeAt(i);IB=await c.decodeAudioData(u.buffer)}catch(e){IBP=null}})())}
function introStop(ms){if(!IS||!AC)return;const g=IGN,s=IS,n=AC.currentTime;IS=null;try{g.gain.cancelScheduledValues(n);g.gain.setValueAtTime(g.gain.value,n);g.gain.linearRampToValueAtTime(0,n+ms/1000);s.stop(n+ms/1000+.05)}catch(e){}}
