    front=`<path d="M${cx-32} ${cy-4} A32 32 0 0 1 ${cx+32} ${cy-4} Q${cx} ${cy-20} ${cx-32} ${cy-4} Z" fill="${INK}"/><path d="M${cx-29} ${cy-13} Q${cx} ${cy-31} ${cx+29} ${cy-13}" fill="none" stroke="${LS}" stroke-width="6" stroke-linecap="round"/>`;
