const OBT=[['Welcome','Plan, focus and learn in one calm place'],['Plan your day','Tasks, weekly planner, exam countdowns'],['Stay focused','Focus timer, rounds, daily goal'],['Learn and remember','Notes, flashcards, grades'],['Made for every subject','Subjects show up everywhere'],['Study anywhere','Get started or sign in']];
const obWrap=h=>'<div class="scr ob"><div class="ob-screen"><div class="ob-in">'+h+'</div></div></div>';
const obIdx=t=>SCREENS.findIndex(s=>s.t===t);
const OBSPEC=(m)=>({m,h:'A light tick on every tap.',s:'A soft pop on every tap. The intro music has not started yet.'});
function obPlay(){
  S.mute=false;sfx.pop();
  R.onclick=e=>{const b=e.target.closest('[data-act]');if(!b)return;const a=b.dataset.act;
    if(a==='next'){sfx.check();hap('light');go(CUR+1)}
    else if(a==='back'){sfx.tick();hap('tick');go(Math.max(0,CUR-1))}
    else if(a==='skip'){sfx.tick();hap('light');go(obIdx('Study anywhere'))}
    else if(a==='start'){sfx.check();hap('medium');go(obIdx('Intro flow'))}
    else if(a==='login'){sfx.check();hap('light');go(obIdx('Sign in'))}
    else if(a==='google'){sfx.check();hap('medium');go(HOMEI())}}
}
